n=22
out=[[6]*n for _ in range(n)]
def tile(r,c,bg,fg):
    for i in range(5):
        for j in range(5):
            out[r+i][c+j]=bg if i in (0,4) or j in (0,4) else fg
# Based on demo: 8-framed tiles slide left, 2-framed slide right, packing overlaps.
for r,c,frame,inner in [(2,0,8,9),(8,0,8,5),(14,0,8,7),(16,5,8,3),(0,12,2,1),(2,17,2,5),(8,17,2,3),(14,17,2,7)]:
    tile(r,c,frame,inner)
print('\n'.join(' '.join(map(str,row)) for row in out))
